(7298461, 1138148, 46177, '<td valign="top">Pretty tree, like the background.</td>', 'Pretty tree, like the background.', '2015-01-04 01:48:02.000000', NULL, 1),
(7298462, 1136921, 46177, '<td valign="top">I really like your processing on this.</td>', 'I really like your processing on this.', '2015-01-04 01:49:47.000000', NULL, 1),
(7298463, 1138082, 46177, '<td valign="top">Love Cabo, love your shot</td>', 'Love Cabo, love your shot', '2015-01-04 01:50:39.000000', NULL, 1),
(7298465, 1138008, 46177, '<td valign="top">Nice light here, well done, nothing is blown out, well done.</td>', 'Nice light here, well done, nothing is blown out, well done.', '2015-01-04 01:52:08.000000', NULL, 1),
(7298466, 1138248, 46177, '<td valign="top">Very pretty, great colours!</td>', 'Very pretty, great colours!', '2015-01-04 01:52:42.000000', NULL, 1),
(7298468, 1138107, 46177, '<td valign="top">Cool shot, great perspective.</td>', 'Cool shot, great perspective.', '2015-01-04 01:53:20.000000', NULL, 1),
(7298469, 1138205, 46177, '<td valign="top">I like this, love the lens you used just makes it so much more interesting. Very cool bumping this up to 8.</td>', 'I like this, love the lens you used just makes it so much more interesting. Very cool bumping this up to 8.', '2015-01-04 01:54:18.000000', NULL, 1),
(7298470, 1138216, 46177, '<td valign="top">Nice use of the sepia tones, looks almost magical.</td>', 'Nice use of the sepia tones, looks almost magical.', '2015-01-04 01:54:56.000000', NULL, 1),
(7298471, 1138151, 46177, '<td valign="top">Nice light on her hair and face, like the angle as well. Oh and of course she is very pretty.</td>', 'Nice light on her hair and face, like the angle as well. Oh and of course she is very pretty.', '2015-01-04 01:55:51.000000', NULL, 1),
(7298474, 1137656, 46177, '<td valign="top">Great colour tones in this, interesting how the light is on the picture but my focus is still on the man. Nicely done!</td>', 'Great colour tones in this, interesting how the light is on the picture but my focus is still on the man. Nicely done!', '2015-01-04 02:08:25.000000', NULL, 1),
(7298475, 1137863, 46177, '<td valign="top">Nicely done, great contrast.</td>', 'Nicely done, great contrast.', '2015-01-04 02:09:41.000000', NULL, 1),
(7298476, 1138203, 46177, '<td valign="top">What a gorgeous sky, love the reflections in the water.</td>', 'What a gorgeous sky, love the reflections in the water.', '2015-01-04 02:10:21.000000', NULL, 1),
(7298477, 1136642, 46177, '<td valign="top">This has a very calming mood, nicely done.</td>', 'This has a very calming mood, nicely done.', '2015-01-04 02:12:43.000000', NULL, 1),
(7298478, 1137008, 46177, '<td valign="top">The infrared is interesting but I wish there was more room at the top of the picture, it just seems a little crowded to me.</td>', 'The infrared is interesting but I wish there was more room at the top of the picture, it just seems a little crowded to me.', '2015-01-04 02:21:56.000000', NULL, 1),
(7298479, 1137578, 46177, '<td valign="top">I like the tones and shadows and the light ins nice, I am just not sure about the crop, I think I would have like it better if there was more sky.</td>', 'I like the tones and shadows and the light ins nice, I am just not sure about the crop, I think I would have like it better if there was more sky.', '2015-01-04 02:24:17.000000', NULL, 1),
(7298480, 1138251, 46177, '<td valign="top">Interesting pattern but I wish there was more contrast.</td>', 'Interesting pattern but I wish there was more contrast.', '2015-01-04 02:25:32.000000', NULL, 1),
(7298483, 1138140, 46177, '<td valign="top">Something spooky and very lonely about this shot, it draws you in, I like it!</td>', 'Something spooky and very lonely about this shot, it draws you in, I like it!', '2015-01-04 02:31:34.000000', NULL, 1),
(7298496, 1137569, 159723, '<td valign="top">Lovely light and colours! In my eyes just enough blur on the back- and foreground!</td>', 'Lovely light and colours! In my eyes just enough blur on the back- and foreground!', '2015-01-04 05:09:45.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7298497, 1137966, 159723, '<td valign="top">For me the foreground is a bit distracting, but the middle and the background, especially the top left, is fantastic!</td>', 'For me the foreground is a bit distracting, but the middle and the background, especially the top left, is fantastic!', '2015-01-04 05:14:02.000000', NULL, 1),
(7298498, 1138140, 159723, '<td valign="top">Lovely mute colours!</td>', 'Lovely mute colours!', '2015-01-04 05:17:40.000000', NULL, 1),
(7298500, 1138177, 159723, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2015-01-04 05:21:17.000000', NULL, 1),
(7298588, 1138177, 173844, '<td valign="top">The overall delicacy and subtly of colors are, to use a word that shouts amid such serenity, glorious.  I suddenly feel imprisoned within my apartment.  That the sky, at about half the image, suitably balances the forest is most impressive.  One of two personal favorites.</td>', 'The overall delicacy and subtly of colors are, to use a word that shouts amid such serenity, glorious.  I suddenly feel imprisoned within my apartment.  That the sky, at about half the image, suitably balances the forest is most impressive.  One of two personal favorites.', '2015-01-04 12:32:24.000000', NULL, 1),
(7298604, 1138078, 2553, '<td valign="top">Love this.  I think it will be nice for him to have this someday to remind him of his childhood.</td>', 'Love this.  I think it will be nice for him to have this someday to remind him of his childhood.', '2015-01-04 13:23:57.000000', NULL, 1),
(7298606, 1138079, 2553, '<td valign="top">While I really do like this image, I would have found a more contrasty image to be more pleasing.  This lacks the "pop" I would have expected in such a cool image of a city scene.</td>', 'While I really do like this image, I would have found a more contrasty image to be more pleasing.  This lacks the "pop" I would have expected in such a cool image of a city scene.', '2015-01-04 13:29:41.000000', NULL, 1),
(7298619, 1137726, 176157, '<td valign="top">This is great,</td>', 'This is great,', '2015-01-04 14:03:48.000000', NULL, 1),
(7298620, 1137815, 176157, '<td valign="top">Great photo.</td>', 'Great photo.', '2015-01-04 14:06:41.000000', NULL, 1),
(7298622, 1138116, 176157, '<td valign="top">Did a deer do that?</td>', 'Did a deer do that?', '2015-01-04 14:08:57.000000', NULL, 1),
(7298623, 1137519, 176157, '<td valign="top">awesome!</td>', 'awesome!', '2015-01-04 14:09:30.000000', NULL, 1),
(7298627, 1137905, 176157, '<td valign="top">I know that look:  "I really want that Michael Kors purse..."  <br/>How can you say "no?"  You can''t.   Very nice photo.</td>', 'I know that look:  "I really want that Michael Kors purse..."  How can you say "no?"  You can''t.   Very nice photo.', '2015-01-04 14:22:04.000000', NULL, 1),
(7298642, 1138201, 173844, '<td valign="top">A beautiful shot without the surging wave, but then here it is and the image is supercharged.  Great immediacy.  I''m guessing Long Island Sound.  One of two personal favorites.</td>', 'A beautiful shot without the surging wave, but then here it is and the image is supercharged.  Great immediacy.  I''m guessing Long Island Sound.  One of two personal favorites.', '2015-01-04 16:28:23.000000', NULL, 1),
(7298644, 1137966, 173844, '<td valign="top">Divine colors.  That Siamese cat on the right looks about to pounce on the foreground jewel.</td>', 'Divine colors.  That Siamese cat on the right looks about to pounce on the foreground jewel.', '2015-01-04 16:32:13.000000', NULL, 1),
(7298649, 1137696, 173844, '<td valign="top">Wonderful light, atmosphere, colors, grouping of trees and, of course, ducks.  A magical moment.  And a fine argument for cameras.</td>', 'Wonderful light, atmosphere, colors, grouping of trees and, of course, ducks.  A magical moment.  And a fine argument for cameras.', '2015-01-04 16:42:32.000000', NULL, 1),
(7298650, 1137888, 173844, '<td valign="top">Works quite well as a naturalistic study, but viewed as an abstract it''s just wondrous.</td>', 'Works quite well as a naturalistic study, but viewed as an abstract it''s just wondrous.', '2015-01-04 16:45:36.000000', NULL, 1),
(7298651, 1138008, 173844, '<td valign="top">A comely paean to industry.</td>', 'A comely paean to industry.', '2015-01-04 16:47:56.000000', NULL, 1),
(7298652, 1137562, 173844, '<td valign="top">Fine title for this confluence of the present and the ancient, elegantly composed and executed.</td>', 'Fine title for this confluence of the present and the ancient, elegantly composed and executed.', '2015-01-04 16:55:55.000000', NULL, 1),
(7298657, 1138252, 173844, '<td valign="top">Unusual, uneasy but ultimately successful balance among the sky, tree and mausoleums.  Much appreciated.</td>', 'Unusual, uneasy but ultimately successful balance among the sky, tree and mausoleums.  Much appreciated.', '2015-01-04 17:17:40.000000', NULL, 1),
(7298659, 1137815, 173844, '<td valign="top">Beautiful photo.  Has a Madonna and child feel.</td>', 'Beautiful photo.  Has a Madonna and child feel.', '2015-01-04 17:19:59.000000', NULL, 1),
(7298660, 1138243, 173844, '<td valign="top">Rhythmic, tranquil and in lovely light.  Well seen.</td>', 'Rhythmic, tranquil and in lovely light.  Well seen.', '2015-01-04 17:22:56.000000', NULL, 1),
(7298662, 1138019, 173844, '<td valign="top">A great title that steers the viewer into the story.  Beautifully composed and realized.  And those sun rays, too!  Superior stuff.</td>', 'A great title that steers the viewer into the story.  Beautifully composed and realized.  And those sun rays, too!  Superior stuff.', '2015-01-04 17:32:25.000000', NULL, 1),
(7298663, 1138194, 173844, '<td valign="top">So well-captured and presented.  A stately stillness prevails.  And there''s silver in them thar skies.</td>', 'So well-captured and presented.  A stately stillness prevails.  And there''s silver in them thar skies.', '2015-01-04 17:35:38.000000', NULL, 1),
(7298664, 1138140, 173844, '<td valign="top">Seemingly minimal but bursting with muted color, texture and mood. Fine picture.</td>', 'Seemingly minimal but bursting with muted color, texture and mood. Fine picture.', '2015-01-04 17:38:26.000000', NULL, 1),
(7298665, 1138215, 173844, '<td valign="top">Great detail, pose and immediacy.  What a beautiful animal, and the photographer has done him or her justice.</td>', 'Great detail, pose and immediacy.  What a beautiful animal, and the photographer has done him or her justice.', '2015-01-04 17:41:42.000000', NULL, 1),
(7298666, 1138184, 173844, '<td valign="top">You can all but hear the music.  Nicely composed.</td>', 'You can all but hear the music.  Nicely composed.', '2015-01-04 17:43:16.000000', NULL, 1),
(7298667, 1138235, 173844, '<td valign="top">Very nice waterfall.  Is that ice on the right?</td>', 'Very nice waterfall.  Is that ice on the right?', '2015-01-04 17:58:05.000000', NULL, 1),
(7298668, 1137292, 173844, '<td valign="top">The huge sky lends intimacy to this vast metropolis. The mid-ground colored buildings are very appealing and the fore-ground structure ties it all together.  Fine photo.</td>', 'The huge sky lends intimacy to this vast metropolis. The mid-ground colored buildings are very appealing and the fore-ground structure ties it all together.  Fine photo.', '2015-01-04 18:02:19.000000', NULL, 1),
(7298669, 1138195, 173844, '<td valign="top">Enticingly mysterious and dizzying.  I can''t quite pin down the complex emotion it''s eliciting, but it sure holds my attention.<br/>Utterly subjective thought --  this might look like more of a piece without the left hand quarter.</td>', 'Enticingly mysterious and dizzying.  I can''t quite pin down the complex emotion it''s eliciting, but it sure holds my attention.Utterly subjective thought --  this might look like more of a piece without the left hand quarter.', '2015-01-04 18:09:33.000000', NULL, 1),
(7298670, 1138233, 173844, '<td valign="top">Artistically and philosophically engaging.  Great composition and balance.  The more I look at this the more I appreciate it.</td>', 'Artistically and philosophically engaging.  Great composition and balance.  The more I look at this the more I appreciate it.', '2015-01-04 18:14:04.000000', NULL, 1),
(7298671, 1138199, 173844, '<td valign="top">Very nice flow and balance.</td>', 'Very nice flow and balance.', '2015-01-04 18:15:03.000000', NULL, 1),
(7298672, 1137822, 173844, '<td valign="top">Exciting transition.</td>', 'Exciting transition.', '2015-01-04 18:16:24.000000', NULL, 1),
(7298673, 1137726, 173844, '<td valign="top">Simple, elegant and humanly engaging. (Humanly engaging?)</td>', 'Simple, elegant and humanly engaging. (Humanly engaging?)', '2015-01-04 18:18:46.000000', NULL, 1),
(7298674, 1138147, 173844, '<td valign="top">A transfixing marvel.</td>', 'A transfixing marvel.', '2015-01-04 18:19:17.000000', NULL, 1),
(7298675, 1137519, 173844, '<td valign="top">Wonderful macro.</td>', 'Wonderful macro.', '2015-01-04 18:19:45.000000', NULL, 1),
(7298676, 1138112, 173844, '<td valign="top">Majestic.  Great lines.</td>', 'Majestic.  Great lines.', '2015-01-04 18:21:24.000000', NULL, 1),
(7298677, 1137008, 173844, '<td valign="top">Great elucidation of the marvelous transformative  power of magnification.</td>', 'Great elucidation of the marvelous transformative  power of magnification.', '2015-01-04 18:25:39.000000', NULL, 1),
(7298678, 1137642, 173844, '<td valign="top">Nice photograph.  Lots of glow.</td>', 'Nice photograph.  Lots of glow.', '2015-01-04 18:26:56.000000', NULL, 1),
(7298679, 1137846, 173844, '<td valign="top">Lovely stream and forest.  Is that Angkor Wat in the background.</td>', 'Lovely stream and forest.  Is that Angkor Wat in the background.', '2015-01-04 18:30:32.000000', NULL, 1),
(7298895, 1138243, 114285, '<td valign="top">Extremeley pleasant to me!</td>', 'Extremeley pleasant to me!', '2015-01-05 03:13:22.000000', NULL, 1),
