(7299947, 1137519, 19825, '<td valign="top">Bug macros aren''t generally my thing, but this one has a twist. Nicely done.</td>', 'Bug macros aren''t generally my thing, but this one has a twist. Nicely done.', '2015-01-07 16:35:57.000000', NULL, 1),
(7299949, 1138140, 19825, '<td valign="top">Simple, quiet beauty. Well captured (and processed).</td>', 'Simple, quiet beauty. Well captured (and processed).', '2015-01-07 16:36:36.000000', NULL, 1),
